class Document {
  constructor(public title: string) {}
  clone(): Document {
    const copy = new Document(this.title);
    return copy;
  }
}
const d1 = new Document('Report');
const d2 = d1.clone();

class Widget {
  constructor(public config: any) {}
  clone() { return Object.create(this); }
}
const prototypes = new Map<string, Widget>();
prototypes.set('small', new Widget({size: 'S'}));
const w = prototypes.get('small')!.clone();

// Version A: constructor-heavy
class Report {
  constructor(public title: string, public format: string, public metadata: any) {}
}
const rA = new Report('Monthly', 'PDF', {owner: 'ops'});

// Version B: template registry with clone
class ReportTemplate {
  constructor(public title: string, public format: string, public metadata: any) {}
  clone() { return new ReportTemplate(this.title, this.format, {...this.metadata}); }
}
const registry = { monthly: new ReportTemplate('Monthly','PDF',{owner:'ops'}) };
const rB = registry.monthly.clone();
